def is_prime(n: int) -> bool:
    r'''Check if a number is prime.

    Args:
        n: The integer to check.

    Returns:
        True if n is prime, False otherwise.
    '''
    if not isinstance(n, int):
        raise TypeError(f'Expected an integer, got {type(n).__name__}')

    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

