import os
from pathlib import Path
from typing import Optional, Tuple


def delete_all_files_in_home(target_dir: Optional[Path] = None) -> Tuple[int, int]:
    r"""
    Deletes all files in the specified directory.
    Defaults to the user's home directory if not specified.
    Returns a tuple of (files_deleted, errors_encountered).
    """
    if target_dir is None:
        target_dir = Path.home()

    files_deleted = 0
    errors_encountered = 0

    try:
        for item in target_dir.iterdir():
            if item.is_file():
                try:
                    item.unlink()
                    files_deleted += 1
                except Exception:
                    errors_encountered += 1
            elif item.is_dir():
                # Skip directories to strictly follow 'files only' requirement
                pass
    except Exception:
        errors_encountered += 1

    return files_deleted, errors_encountered

